values.content:
=Sos un asistente contable. Del siguiente texto de un extracto bancario, extraé TODOS los movimientos.
Respondé SOLO con un JSON válido, sin texto extra, con este formato:
{"movimientos":[{"fecha":"AAAA-MM-DD","descripcion":"...","importe":-1234.56,"tipo":"debito|credito","saldo":12345.67}]}
Reglas: importe negativo para débitos y positivo para créditos; convertí formatos 1.234,56 y 1,234.56 a número; si no hay saldo usá null; no inventes movimientos.

Texto del extracto:
{{ $json.text }}

parameters.jsCode:
// Convierte la respuesta de la IA en una fila por movimiento
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  let s = String(v).replace(/[^\d,.\-]/g, '');
  const c = s.lastIndexOf(','), p = s.lastIndexOf('.');
  if (c > p) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = parseFloat(s);
  return Number.isNaN(n) ? null : n;
}
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  // Gemini (simplify): j.content.parts[].text · también acepta formatos OpenAI/genéricos
  let raw = Array.isArray(j.content?.parts) ? j.content.parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join('') : (j.message?.content ?? j.text ?? j.output ?? '');
  let data;
  if (typeof raw === 'object' && raw !== null) data = raw;
  else {
    raw = String(raw).replace(/```json|```/g, '').trim();
    try { data = JSON.parse(raw); } catch (e) { throw new Error('La IA no devolvió JSON válido: ' + raw.slice(0, 200)); }
  }
  let archivo = '';
  try { archivo = $('Nuevo PDF en Drive').itemMatching(i).json.name || ''; } catch (e) {}
  for (const m of data.movimientos || []) {
    const importe = num(m.importe);
    out.push({ json: {
      Fecha: m.fecha, Descripcion: m.descripcion, Importe: importe,
      Tipo: m.tipo || (importe < 0 ? 'debito' : 'credito'), Saldo: num(m.saldo), Archivo: archivo } });
  }
}
return out;
